(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);let W=800,H=600,DPR=1,started=false,interior=false,toastTimer=0,muted=false,saveTimer=0,sceneTime=0,weatherIndex=0,keys={},touch={},player={x:850,y:770,speed:178,face:0},money=2450,xp=0,job='',mission=0,progress=0,doingJob=0,sidebarShown=false;let last=performance.now();
const names=['Ein guter erster Eindruck','Ein kleiner Gefallen','Ein Zuhause auf Zeit','Die Spur im Regen','Licht im Olpetal'];const texts=['Triff Mara am Marktplatz. Sie kennt hier jeden und hat bestimmt einen Tipp für den Start.','Bring Maras Einkauf zum Café am Kirchplatz.','Sieh dir das freie Zimmer über der Bäckerei an.','Folge der Spur bis zur alten Bushaltestelle.','Finde den geheimnisvollen Umschlag am Biggesee.'];const targets=[{x:1000,y:745,name:'MARKTPLATZ'},{x:1200,y:515,name:'CAFÉ AM KIRCHPLATZ'},{x:540,y:560,name:'ZIMMER ÜBER DER BÄCKEREI'},{x:1480,y:1010,name:'ALTE BUSHALTESTELLE'},{x:1710,y:250,name:'BIGGESEE-UFER'}];const people=[{x:1000,y:745,n:'Mara',color:'#b65a3a',r:15},{x:1195,y:515,n:'Cafébesitzer',color:'#435e5d',r:14},{x:1490,y:1018,n:'',color:'#5c6948',r:14}];const buildings=[{x:410,y:420,w:240,h:170,name:'BÄCKEREI',color:'#d9b786',roof:'#9c6e53',type:'shop',door:[535,590]},{x:735,y:300,w:190,h:155,name:'OLPE BANK',color:'#c7c7b9',roof:'#74847e',type:'bank',door:[830,455]},{x:1085,y:320,w:225,h:165,name:'RATHAUS',color:'#d8d1bb',roof:'#687d76',type:'public',door:[1190,485]},{x:1330,y:650,w:250,h:170,name:'CAFÉ AM KIRCHPLATZ',color:'#d7b29a',roof:'#955d4d',type:'cafe',door:[1450,820]},{x:300,y:700,w:210,h:180,name:'ALTSTADT · HAUS 12',color:'#b9c9ad',roof:'#536c58',type:'home',door:[400,880]},{x:520,y:1060,w:240,h:180,name:'STADTBIBLIOTHEK',color:'#c5d0c8',roof:'#667c78',type:'public',door:[640,1060]},{x:1050,y:1070,w:250,h:185,name:'FEUERWACHE OLPE',color:'#d7c8b2',roof:'#a25b4b',type:'fire',door:[1170,1070]},{x:1470,y:380,w:220,h:160,name:'WOHNHAUS',color:'#d8c6a9',roof:'#81664e',type:'home',door:[1530,540]},{x:1680,y:700,w:210,h:170,name:'MARKT & MEHR',color:'#d8d1b3',roof:'#839568',type:'shop',door:[1770,870]}];const bins=[{x:720,y:690,done:false},{x:1270,y:900,done:false},{x:920,y:1120,done:false}];const obstacles=buildings.map(b=>({x:b.x-8,y:b.y-8,w:b.w+16,h:b.h+16}));
function resize(){const r=canvas.getBoundingClientRect();DPR=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0)}new ResizeObserver(resize).observe(canvas);resize();
function toast(s){const t=$('toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2350)}function updateUI(){ $('money').textContent=money.toLocaleString('de-DE');$('xp').textContent=xp;$('missionTitle').textContent=names[Math.min(mission,4)]||'Ein neuer Anfang';$('missionText').textContent=texts[Math.min(mission,4)]||'Das Olpetal liegt dir zu Füßen. Was machst du als Nächstes?';$('missionStep').textContent=`0${Math.min(mission+1,5)} / 05`;$('targetName').textContent=targets[Math.min(mission,4)].name;$('progressBar').style.width=`${Math.min(100,progress*25)}%`;if(job){$('jobTitle').textContent=job;$('jobSub').textContent=`Schicht aktiv · ${doingJob}/3 Aufträge`;}const d=Math.round(Math.hypot(player.x-targets[Math.min(mission,4)].x,player.y-targets[Math.min(mission,4)].y));$('distance').textContent=`${d} m`;updateNearby();}
function updateNearby(){const items=[['⌂','Bäckerei','80 m'],['▤','Olpe Bank','120 m'],['☕','Café am Kirchplatz','210 m']];$('nearbyList').innerHTML=items.map(x=>`<div class="nearby-item"><span class="nearby-icon">${x[0]}</span><span>${x[1]}</span><small>${x[2]}</small></div>`).join('')}
function save(){try{localStorage.setItem('olpetal-save',JSON.stringify({money,xp,job,mission,progress,doingJob,player:{x:player.x,y:player.y},bins:bins.map(b=>b.done)}));toast('Spielstand gespeichert.')}catch(e){toast('Speichern nicht möglich.')}}function load(){try{const d=JSON.parse(localStorage.getItem('olpetal-save')||'null');if(d){money=d.money??money;xp=d.xp||0;job=d.job||'';mission=d.mission||0;progress=d.progress||0;doingJob=d.doingJob||0;if(d.player)player={...player,...d.player};(d.bins||[]).forEach((v,i)=>bins[i].done=v);}}catch(e){}}
function worldToScreen(x,y,camera){return[x-camera.x+W/2,y-camera.y+H/2]}
function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function drawGround(cam){ctx.fillStyle='#b9c9ad';ctx.fillRect(0,0,W,H);let ox=(-cam.x+W/2)%90,oy=(-cam.y+H/2)%90;for(let x=ox-90;x<W+90;x+=90)for(let y=oy-90;y<H+90;y+=90){ctx.fillStyle=(Math.floor((x-ox)/90+(y-oy)/90)%2?'#b8c8a9':'#bdcdb2');ctx.fillRect(x,y,90,90)}
// park & landscape edges
ctx.fillStyle='#a7c39b';ctx.fillRect(...worldToScreen(-500,0,cam),380,1800);ctx.fillRect(...worldToScreen(1970,0,cam),500,1800);ctx.fillStyle='#abc8d0';ctx.beginPath();let p=worldToScreen(0,-100,cam);ctx.moveTo(p[0],p[1]);for(let y=-100;y<1800;y+=50){let q=worldToScreen(1940+Math.sin(y*.007)*36,y,cam);ctx.lineTo(q[0],q[1])}p=worldToScreen(2090,1800,cam);ctx.lineTo(p[0],p[1]);p=worldToScreen(0,1800,cam);ctx.lineTo(p[0],p[1]);ctx.closePath();ctx.fill();
// roads
ctx.fillStyle='#9b9e91';[[0,620,2000,94],[0,950,2000,82],[960,0,95,1500],[420,260,70,900],[1330,180,72,960],[170,520,600,62],[1220,570,740,58]].forEach(a=>{let p=worldToScreen(a[0],a[1],cam);ctx.fillRect(p[0],p[1],a[2],a[3])});ctx.strokeStyle='#e7e2c6';ctx.lineWidth=2;ctx.setLineDash([17,15]);[[0,666,2000,0],[0,990,2000,0],[1005,0,0,1500],[450,260,0,900],[1365,180,0,960]].forEach(a=>{let p=worldToScreen(a[0],a[1],cam);ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(p[0]+a[2],p[1]+a[3]);ctx.stroke()});ctx.setLineDash([]);
// pavements and plaza
let p=worldToScreen(755,680,cam);ctx.fillStyle='#d3d0be';ctx.fillRect(p[0],p[1],440,190);ctx.fillStyle='#c6c3b1';for(let x=0;x<440;x+=24){ctx.fillRect(p[0]+x,p[1],1,190)}for(let y=0;y<190;y+=24)ctx.fillRect(p[0],p[1]+y,440,1);
// church footprint
p=worldToScreen(900,480,cam);ctx.fillStyle='#ddd5c1';ctx.fillRect(p[0],p[1],110,105);ctx.fillStyle='#8c8b77';ctx.fillRect(p[0]+31,p[1]-45,48,90);ctx.fillStyle='#656a60';ctx.beginPath();ctx.moveTo(p[0]+31,p[1]-45);ctx.lineTo(p[0]+55,p[1]-79);ctx.lineTo(p[0]+79,p[1]-45);ctx.fill();ctx.fillStyle='#f2e5b7';ctx.fillRect(p[0]+48,p[1]-59,13,16);
}
function drawBuilding(b,cam){const [x,y]=worldToScreen(b.x,b.y,cam);if(x+b.w<-80||x>W+80||y+b.h<-100||y>H+80)return;ctx.fillStyle='#24342b30';ctx.beginPath();ctx.roundRect(x+12,y+15,b.w,b.h,4);ctx.fill();ctx.fillStyle=b.color;ctx.fillRect(x,y,b.w,b.h);ctx.fillStyle=b.roof;ctx.beginPath();ctx.moveTo(x-12,y+8);ctx.lineTo(x+b.w*.12,y-30);ctx.lineTo(x+b.w*.86,y-30);ctx.lineTo(x+b.w+13,y+8);ctx.closePath();ctx.fill();ctx.fillStyle='#ffffff35';ctx.fillRect(x+9,y+10,b.w-18,3);for(let wx=x+20;wx<x+b.w-15;wx+=44){ctx.fillStyle='#77918c';ctx.fillRect(wx,y+26,22,25);ctx.fillStyle='#ffffff85';ctx.fillRect(wx+2,y+28,7,21);ctx.fillStyle='#6c6555';ctx.fillRect(wx,y+70,20,27)}let dx=b.door[0]-b.x,dy=b.door[1]-b.y;ctx.fillStyle='#544d3d';ctx.fillRect(x+dx-12,y+dy-33,24,34);ctx.fillStyle='#e3cc95';ctx.beginPath();ctx.arc(x+dx+6,y+dy-16,1.7,0,Math.PI*2);ctx.fill();rounded(x+6,y+b.h+5,Math.min(116,b.name.length*6+14),17,3,'#f9f8eddd');ctx.fillStyle='#4b5a4f';ctx.font='7px DM Mono,monospace';ctx.fillText(b.name,x+12,y+b.h+16)}
function drawTrees(cam){for(let i=0;i<34;i++){const x=((i*197+237)%2260)-150,y=((i*271+143)%1600)-50;if(x>250&&x<1900&&y>250&&y<1280&&Math.abs(y-665)<130)continue;const [sx,sy]=worldToScreen(x,y,cam);if(sx<-40||sx>W+40||sy<-40||sy>H+40)continue;ctx.fillStyle='#34483633';ctx.beginPath();ctx.ellipse(sx+4,sy+8,15,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=['#56754f','#658357','#4e7049','#758a5b'][i%4];ctx.beginPath();ctx.arc(sx,sy,12+(i%4),0,Math.PI*2);ctx.fill();ctx.fillStyle='#a7be8170';ctx.beginPath();ctx.arc(sx-4,sy-5,5,0,Math.PI*2);ctx.fill()}}
function drawFurnishings(){const c=ctx; c.fillStyle='#e6dfcd';c.fillRect(0,0,W,H);c.fillStyle='#d3c7ae';for(let x=0;x<W;x+=42)c.fillRect(x,0,1,H);for(let y=0;y<H;y+=42)c.fillRect(0,y,W,1);c.fillStyle='#c7bba2';c.fillRect(0,0,W,13);c.fillRect(0,H-15,W,15);c.fillRect(0,0,13,H);c.fillRect(W-13,0,13,H);c.fillStyle='#9c785d';c.fillRect(W*.43,H-18,W*.14,18);c.fillStyle='#553f32';c.fillRect(W*.43,H-23,W*.14,7); // door
// furniture blocks
rounded(W*.13,H*.18,W*.28,H*.2,6,'#80938b');rounded(W*.14,H*.21,W*.25,H*.14,4,'#a8b8aa');rounded(W*.62,H*.16,W*.21,H*.3,4,'#997552');rounded(W*.64,H*.18,W*.17,H*.22,3,'#c39b6a');rounded(W*.62,H*.57,W*.2,H*.14,5,'#b98164');rounded(W*.66,H*.59,W*.12,H*.1,4,'#d7ad8e');rounded(W*.21,H*.56,W*.16,H*.13,5,'#e7e1d1');ctx.fillStyle='#566454';ctx.fillRect(W*.24,H*.6,W*.1,4);ctx.fillStyle='#758b78';ctx.fillRect(W*.25,H*.59,W*.08,6);ctx.fillStyle='#8c684b';ctx.fillRect(W*.28,H*.75,W*.38,10);ctx.fillStyle='#c6a878';ctx.fillRect(W*.32,H*.69,W*.28,9);ctx.fillStyle='#f0d48b';ctx.beginPath();ctx.arc(W*.77,H*.76,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f9e9bd';ctx.beginPath();ctx.arc(W*.77,H*.76,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e8f0e2';ctx.fillRect(W*.04,H*.1,W*.18,H*.09);ctx.fillRect(W*.78,H*.06,W*.16,H*.08);ctx.fillStyle='#81938b';ctx.fillRect(W*.05,H*.105,W*.16,H*.07);ctx.fillRect(W*.79,H*.065,W*.14,H*.06);}
function drawPlayer(x,y,face,color='#e8ebd9'){ctx.save();ctx.translate(x,y);ctx.fillStyle='#1f2c2844';ctx.beginPath();ctx.ellipse(1,8,9,5,0,0,7);ctx.fill();ctx.fillStyle='#344b47';ctx.beginPath();ctx.ellipse(-3,6,3,5,0,0,7);ctx.ellipse(4,6,3,5,0,0,7);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-7,-8,14,15,5);ctx.fill();ctx.fillStyle='#d7aa82';ctx.beginPath();ctx.arc(0,-12,5.5,0,7);ctx.fill();ctx.fillStyle='#51453b';ctx.beginPath();ctx.arc(-1,-14,5,Math.PI,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-4);ctx.lineTo(Math.cos(face)*8,-4+Math.sin(face)*8);ctx.stroke();ctx.restore()}
function drawPeople(cam){const near=[...people,{x:860,y:610,n:'',color:'#526d70',r:13},{x:1150,y:710,n:'',color:'#d0b38c',r:14},{x:650,y:735,n:'',color:'#94634e',r:13},{x:1540,y:600,n:'',color:'#6b7350',r:13}];near.forEach((p,i)=>{let x=p.x+(started?Math.sin(sceneTime*.00045+i*2)*9:0),y=p.y+(started?Math.cos(sceneTime*.0004+i)*7:0),[sx,sy]=worldToScreen(x,y,cam);drawPlayer(sx,sy,Math.PI/2,p.color);if(p.n&&Math.hypot(player.x-p.x,player.y-p.y)<220){ctx.fillStyle='#f9f8ed';ctx.beginPath();ctx.roundRect(sx-22,sy-37,44,16,4);ctx.fill();ctx.fillStyle='#34433b';ctx.font='9px DM Sans';ctx.textAlign='center';ctx.fillText(p.n,sx,sy-26);ctx.textAlign='left'}})}
function drawBins(cam){bins.forEach((b,i)=>{if(b.done)return;let[sx,sy]=worldToScreen(b.x,b.y,cam);ctx.fillStyle='#344c3c';ctx.fillRect(sx-8,sy-11,16,17);ctx.fillStyle='#769267';ctx.fillRect(sx-10,sy-14,20,5);ctx.fillStyle='#ccd2b3';ctx.fillRect(sx-2,sy-8,4,8);if(Math.hypot(player.x-b.x,player.y-b.y)<60){ctx.strokeStyle='#e0efad';ctx.lineWidth=2;ctx.beginPath();ctx.arc(sx,sy,20+Math.sin(sceneTime*.007)*2,0,7);ctx.stroke()}})}
function interaction(){let nearby=null,min=90;if(interior){$('interaction').classList.add('visible');$('interaction').innerHTML='<kbd>E</kbd><span>RAUM VERLASSEN</span>';return {type:'exit'}}for(const b of buildings){const d=Math.hypot(player.x-b.door[0],player.y-b.door[1]);if(d<min){min=d;nearby={type:'building',obj:b}}}for(let i=0;i<people.length;i++){if(!people[i].n)continue;let d=Math.hypot(player.x-people[i].x,player.y-people[i].y);if(d<min){min=d;nearby={type:'person',obj:people[i]}}}for(const b of bins){if(!b.done){let d=Math.hypot(player.x-b.x,player.y-b.y);if(d<min){min=d;nearby={type:'bin',obj:b}}}}if(nearby){$('interaction').classList.add('visible');let label=nearby.type==='person'?`MIT ${nearby.obj.n} SPRECHEN`:nearby.type==='bin'?'MÜLLTONNE LEEREN':`${nearby.obj.name} BETRETEN`;$('interaction').innerHTML=`<kbd>E</kbd><span>${label}</span>`}else $('interaction').classList.remove('visible');return nearby}
function render(){const cam=interior?{x:0,y:0}:{x:player.x,y:player.y};ctx.setTransform(DPR,0,0,DPR,0,0);if(interior){drawFurnishings();drawPlayer(W/2,H*.78,0);$('interiorLabel').style.display='block';$('locationName').textContent='OLPE · '+(interior.name||'INNENRAUM');}else{$('interiorLabel').style.display='none';$('locationName').textContent='OLPE · INNENSTADT';drawGround(cam);drawTrees(cam);buildings.forEach(b=>drawBuilding(b,cam));drawBins(cam);drawPeople(cam);let[sx,sy]=worldToScreen(player.x,player.y,cam);drawPlayer(sx,sy,player.face);interaction()}if(!started){ctx.fillStyle='#17252122';ctx.fillRect(0,0,W,H)} }
function openInterior(b){interior=b;player.intDoor=b;toast(`Du betrittst: ${b.name}`)}function interact(){const a=interaction();if(!a){toast('Hier gibt es gerade nichts zu tun.');return}if(a.type==='exit'){interior=false;player.x=player.intDoor.door[0];player.y=player.intDoor.door[1]+42;toast('Zurück auf den Straßen von Olpe.');return}if(a.type==='building'){openInterior(a.obj);return}if(a.type==='bin'){a.obj.done=true;money+=job?1000:75;xp+=20;doingJob++;toast(job?'Mülltonne geleert · +1.000 €':'Pfand & Altglas gesammelt · +75 €');updateUI();save();return}if(a.type==='person'){const n=a.obj.n;if(n==='Mara'){if(mission===0){mission++;progress=1;money+=150;xp+=50;toast('Mara: „Willkommen! Bring das hier zum Café am Kirchplatz.“  +150 €');}else if(mission===1){mission++;progress=2;money+=250;xp+=65;toast('Mara: „Perfekt! Schau dir das Zimmer über der Bäckerei an.“  +250 €');}else{toast('Mara: „Schön, dich wiederzusehen. Olpe hat noch viel zu bieten!“');}}else if(mission===1){mission++;progress=2;money+=250;xp+=65;toast('Der Cafébesitzer nimmt die Tüte entgegen. +250 €');}else{toast(`${n}: „Schönes Wetter heute, oder?“`)}updateUI();save()}}
function move(dt){if(!started)return;let dx=0,dy=0;if(keys.KeyW||keys.ArrowUp||touch.up)dy--;if(keys.KeyS||keys.ArrowDown||touch.down)dy++;if(keys.KeyA||keys.ArrowLeft||touch.left)dx--;if(keys.KeyD||keys.ArrowRight||touch.right)dx++;if(!dx&&!dy)return;const l=Math.hypot(dx,dy);dx/=l;dy/=l;player.face=Math.atan2(dy,dx);let speed=player.speed*((keys.ShiftLeft||keys.ShiftRight)?1.65:1);let nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(interior){player.x=nx;player.y=ny;return}const collides=(x,y)=>obstacles.some(o=>x>o.x-12&&x<o.x+o.w+12&&y>o.y-12&&y<o.y+o.h+12);if(!collides(nx,player.y))player.x=nx;if(!collides(player.x,ny))player.y=ny;player.x=Math.max(-300,Math.min(2200,player.x));player.y=Math.max(-100,Math.min(1550,player.y))}
function frame(now){let dt=Math.min(.04,(now-last)/1000);last=now;sceneTime=now;move(dt);const mins=(8*60+15+now/60000)%1440;const h=Math.floor(mins/60),m=Math.floor(mins%60);$('clock').textContent=`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;const day=Math.sin((mins/1440)*Math.PI*2-Math.PI/2);canvas.style.filter=`brightness(${.77+(.23*(day+1)/2)}) saturate(${weatherIndex===1?.75:1})`;render();if(started&&now-saveTimer>30000){saveTimer=now;try{localStorage.setItem('olpetal-save',JSON.stringify({money,xp,job,mission,progress,doingJob,player:{x:player.x,y:player.y},bins:bins.map(b=>b.done)}))}catch(e){}}requestAnimationFrame(frame)}requestAnimationFrame(frame);
function start(){started=true;$('startOverlay').classList.add('hidden');toast('Willkommen in Olpe, Jonas. Geh zum Marktplatz und sprich mit Mara.');if(innerWidth<690){$('sidebar').classList.remove('show')}}
$('startBtn').onclick=start;$('saveBtn').onclick=save;$('soundBtn').onclick=()=>{muted=!muted;$('soundBtn').innerHTML=muted?'♫ <span>STUMM</span>':'♫ <span>SOUND</span>';toast(muted?'Sound ausgeschaltet.':'Sound eingeschaltet.')};$('mapBtn').onclick=()=>$('mapOverlay').classList.add('open');$('closeMap').onclick=()=>$('mapOverlay').classList.remove('open');$('journalBtn').onclick=()=>openModal('Journal');$('jobsBtn').onclick=()=>openModal('Jobs');$('jobAction').onclick=()=>openModal('Jobs');$('settingsBtn').onclick=()=>openModal('Einstellungen');$('modalClose').onclick=closeModal;$('modalBackdrop').onclick=e=>{if(e.target===$('modalBackdrop'))closeModal()};$('touchAction').onclick=interact;
document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='KeyE'&&!e.repeat)interact();if(e.code==='KeyM'&&!e.repeat)$('mapOverlay').classList.toggle('open');if(e.code==='Escape'){closeModal();$('mapOverlay').classList.remove('open')}});document.addEventListener('keyup',e=>keys[e.code]=false);document.querySelectorAll('[data-dir]').forEach(b=>{const d=b.dataset.dir;['pointerdown','touchstart'].forEach(ev=>b.addEventListener(ev,e=>{e.preventDefault();touch[d]=true}));['pointerup','pointerleave','touchend','touchcancel'].forEach(ev=>b.addEventListener(ev,e=>{e.preventDefault();touch[d]=false}))});
